"""Player decision projection, not matchup accuracy or human comprehension tests."""
import subprocess,unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PRELUDE="""const assert=require('node:assert/strict'),E=require('./web_r4/loading-engine.js'),C=require('./web_r4/loading-coach.js'),c=require('./web_r4/loading-data.json');
function run(i=0,s={},p={},risk='BALANCED',period='LEVEL1'){let x=E.exampleInput(c,i);x.schema_version='lol-coach-loading-input-v4';x.preferences={risk};x.scenario={standard:'lane-standard-v1',overrides:s};x.planning={basis:'loading-plan-example-v1',overrides:p};const r=E.analyze(x,c);r.coach=C.evaluate(r,c,r.input.scenario,period);return r;}
"""
class PlayerPlanboardTests(unittest.TestCase):
 def node(self,body):
  r=subprocess.run(['node','-e',PRELUDE+body],cwd=ROOT,capture_output=True,text=True)
  self.assertEqual(r.returncode,0,r.stderr[-4000:])
 def test_loading_direction_has_four_decisions_and_bounded_exceptions(self):
  self.node("for(const i of [0,1,2,3,4]){const a=run(i).coach.planboard,b=a.loading_summary;assert(b,'missing compact loading direction');assert.deepEqual(b.items.map(v=>v.id),['lane','growth','operations','fight']);assert(b.changes.length<=3);assert(b.items.every(v=>v.conclusion&&v.support));assert(!b.items[0].conclusion.includes('막타 중심으로 천천히'));}const a=run().coach.planboard;assert.match(a.loading_summary.items[0].conclusion,/사거리|압박/);const low=run(0,{resources:'LOW'}).coach.planboard;assert.match(low.loading_summary.items[0].conclusion,/CS|경험치|수급/);assert.notEqual(low.loading_summary.items[0].conclusion,a.loading_summary.items[0].conclusion);assert.deepEqual(run(0,{}, {},'LOSS_LIMIT').coach.planboard.loading_summary.items[1],run(0,{}, {},'OPPORTUNITY').coach.planboard.loading_summary.items[1]);")
 def test_loading_conclusion_tracks_active_scope_not_initial_pressure(self):
  self.node("for(const state of [{wave:'UNKNOWN'},{wave:'UNDER_TOWER'},{wave:'INCOMING'},{engage:'THEIRS'},{engage:'OURS'}]){const a=run(0,state).coach.planboard.loading_summary.items[0];assert(!/사거리 견제로 막타 접근을 늦추고|먼저 처리 여유/.test(a.conclusion+' '+a.support));}const a=run(0,{}, {goal:'RECALL'}).coach.planboard.loading_summary.items[0];assert.match(a.conclusion,/귀환|구매/);assert(!/먼저 처리 여유/.test(a.support));for(const i of [0,1,2,3,4,5]){const b=run(i,{}, {goal:'PRESSURE'},'BALANCED','LEVEL2').coach.planboard.loading_summary;assert(!b.items.slice(2).some(x=>/바꾼다|끊기면/.test(x.support)),'do not append extra switches beyond shared three');assert(b.items.every(x=>(x.conclusion.match(/\. /g)||[]).length===0));}")
 def test_fiora_statistics_expert_and_counterplay_bridge_does_not_invent_strength(self):
  self.node("const a=run(1).coach,b=a.planboard.evidence_bridge;assert(b,'missing statistical to guide bridge');assert.equal(b.statistics.matchup.outcome.n,1);assert.equal(b.statistics.matchup.matchup.points.length,0);assert.equal(b.statistics.tactical_confirmation,false);assert.equal(b.expert.source_ids.length,2);assert.match(b.expert.plan,/수급|마나/);assert.equal(b.counterplay.opponent_goal,a.planboard.matchup_playbook.theirs.purpose);assert.equal(b.counterplay.wave_plan,a.planboard.wave.label);assert.equal(b.counterplay.growth,a.planboard.loading_summary.items[1].conclusion);for(const p of a.periods)for(const m of Object.values(p.metrics))assert.equal(m.assessment,'INSUFFICIENT');const k={...c,coaching_knowledge:structuredClone(require('./web_r4/loading-knowledge.json'))};delete k.coaching_knowledge.statistical_context.matchups.E;const x=E.exampleInput(k,1),r=E.analyze(x,k).coach;assert.equal(r.planboard.evidence_bridge.statistics.matchup,null);assert.equal(r.supported,true);assert.equal(r.planboard.loading_summary.items.length,4); ")
 def test_default_has_three_time_scales_and_four_separate_axes(self):
  self.node("const r=E.analyze(E.exampleInput(c,0),c),b=r.coach.planboard;assert(b,'missing player planboard');assert(b.lane.overall_goal);assert(b.lane.milestone.goal);assert(b.wave.purpose);assert.equal(b.wave.plan_id,'ACQUIRE_PUSH');for(const k of ['pace','pressure','exposure','resources'])assert(b.wave.axes[k]);assert(b.wave.next_wave);assert.equal(b.wave.state.minion_size,'UNOBSERVED');assert.equal(b.wave.completed,false);assert.equal(b.reminders.length,3);assert(b.quick_scenarios.length<=2);")
 def test_versioned_hypotheses_are_not_observations(self):
  self.node("const r=run(0,{}, {enemy_jungle:'AWAY',enemy_support:'ABSENT'});assert.equal(r.input.schema_version,'lol-coach-loading-input-v4');assert.equal(r.coach.context.observations.resources,null);assert.equal(r.coach.planboard.context.origin,'HYPOTHETICAL_LOADING_EXAMPLE');assert.equal(r.coach.planboard.context.actual_enemy_positions,null);let x=E.exampleInput(c,0);x.schema_version='lol-coach-loading-input-v3';x.preferences={risk:'BALANCED'};x.scenario={standard:'lane-standard-v1',overrides:{}};const a=E.analyze(x,c);assert(a.coach.planboard);x.planning={basis:'loading-plan-example-v1',overrides:{}};assert.throws(()=>E.analyze(x,c));x.schema_version='lol-coach-loading-input-v4';x.planning.overrides.actual_enemy_x=10;assert.throws(()=>E.analyze(x,c));")
 def test_jungle_exposure_is_not_processing_speed_or_automatic_retreat(self):
  self.node("const a=run().coach.planboard,b=run(0,{}, {enemy_jungle:'NEAR'}).coach.planboard;assert.equal(a.wave.plan_id,b.wave.plan_id);assert.equal(a.wave.axes.pace.id,b.wave.axes.pace.id);assert.notEqual(a.wave.axes.exposure.id,b.wave.axes.exposure.id);assert.notEqual(a.wave.axes.pressure.id,b.wave.axes.pressure.id);assert(b.wave.handling.includes('막타'));assert(b.wave.next_wave.includes('상대 쪽'));assert.equal(a.context.planning.overrides.enemy_jungle,undefined);")
 def test_wave_position_and_purpose_change_processing_but_crash_is_not_completed(self):
  self.node("const incoming=run(0,{wave:'INCOMING'}).coach.planboard,tower=run(0,{wave:'UNDER_TOWER'}).coach.planboard,ret=run(0,{wave:'RETURNING'}).coach.planboard;assert.equal(incoming.wave.plan_id,'TRIM_RECEIVE');assert.equal(tower.wave.plan_id,'TOWER_CS');assert.equal(ret.wave.plan_id,'RETURNING');const no=run(0,{wave:'BUILDING'},{goal:'RECALL'}).coach.planboard,yes=run(0,{wave:'BUILDING'},{goal:'RECALL',clear_window:'OPEN'}).coach.planboard;assert.notEqual(no.wave.plan_id,'FAST_PUSH');assert.equal(yes.wave.plan_id,'FAST_PUSH');assert.equal(yes.wave.completed,false);assert(yes.wave.next_wave.includes('포탑'));assert.notEqual(yes.wave.purpose,no.wave.purpose);assert.notEqual(run(0,{resources:'LOW'},{goal:'RECALL',clear_window:'OPEN'}).coach.planboard.wave.plan_id,'FAST_PUSH');")
 def test_support_absence_opens_limited_space_not_guaranteed_kill(self):
  self.node("const a=run().coach.planboard,b=run(0,{}, {enemy_support:'ABSENT'}).coach.planboard;assert.notEqual(a.wave.combat,b.wave.combat);assert(b.wave.combat.includes('카이사'));assert(b.wave.change_if.includes('복귀'));assert(!b.wave.diagram.enemies.includes('Nautilus'));assert.equal(b.fight.kill,'UNDETERMINED');const near=run(0,{}, {enemy_support:'ABSENT',enemy_jungle:'NEAR'}).coach.planboard;assert.equal(near.wave.axes.pressure.id,'LIMITED');assert(!near.wave.combat.includes('무조건'));")
 def test_risk_changes_feasible_execution_not_strength_or_source(self):
  self.node("const a=run(0,{}, {},'LOSS_LIMIT'),b=run(0,{}, {},'OPPORTUNITY');assert.deepEqual(a.coach.periods,b.coach.periods);assert.deepEqual(a.coach.evidence,b.coach.evidence);assert.notEqual(a.coach.planboard.wave.combat,b.coach.planboard.wave.combat);assert(b.coach.planboard.choice.cost);assert(b.coach.planboard.choice.reserve);const x=run(0,{wave:'BUILDING'},{goal:'RECALL',clear_window:'OPEN'},'LOSS_LIMIT'),y=run(0,{wave:'BUILDING'},{goal:'RECALL',clear_window:'OPEN'},'OPPORTUNITY');assert.equal(x.coach.planboard.choice.id,y.coach.planboard.choice.id);assert.equal(y.coach.planboard.choice.same_across_preferences,true);")
 def test_unconfirmed_tower_reach_unknowns_and_patch_do_not_become_safe(self):
  self.node("const u=run(0,{wave:'UNKNOWN'}).coach.planboard;assert.equal(u.wave.diagram.supported,false);assert.equal(u.wave.plan_id,'CHECK_WAVE');assert.equal(u.overall.lanes.find(l=>l.position==='TOP').priority,'INSUFFICIENT');let x=E.exampleInput(c,0);x.patch='1.1';const r=E.analyze(x,c);assert.equal(r.coach.planboard.wave.diagram.supported,false);assert.equal(r.coach.planboard.lane.basis,'INSUFFICIENT');assert(!r.coach.planboard.headline.includes('우세'));")
 def test_context_order_and_role_changes_have_real_meaning(self):
  self.node("const x=run().input,a=E.analyze(x,c).coach.planboard;x.allies.reverse();x.enemies.reverse();assert.deepEqual(E.analyze(x,c).coach.planboard,a);const f=run(1).coach.planboard;assert.equal(f.operations.mode,'SIDE_RETURN');assert.notEqual(a.operations.placement,f.operations.placement);assert(f.fight.start.includes('피오라'));let y=run().input;y.allies.find(p=>p.position==='SUPPORT').position=null;assert.equal(E.analyze(y,c).coach.planboard.lane.basis,'INSUFFICIENT');")
 def test_growth_changes_plan_not_global_reversal(self):
  self.node("const a=run(4).coach.planboard,b=run(4,{}, {},'BALANCED','KAISA_EVOLVED_ACCESS').coach.planboard;assert.notEqual(a.lane.milestone.goal,b.lane.milestone.goal);assert(b.operations.growth.includes('진화'));assert.equal(b.growth.global_reversal,'UNDETERMINED');assert(b.growth.remaining_strength.includes('견제'));assert(b.wave.change_if.length);")
 def test_both_sides_counterplans_are_matched_to_duo_and_period(self):
  self.node("const a=run().coach.planboard;assert(a.matchup_playbook,'missing two-sided playbook');for(const side of ['ours','theirs'])for(const k of ['purpose','means','look_for','avoid','switch_when'])assert(a.matchup_playbook[side][k]);assert(a.matchup_playbook.theirs.means.includes('노틸러스'));assert(a.matchup_playbook.theirs.means.includes('카이사'));assert.equal(a.coverage.status,'BASIC_PLAN_CONDITIONAL');const b=run(2).coach.planboard;assert(b.matchup_playbook.theirs.means.includes('알리스타'));assert(b.matchup_playbook.ours.means.includes('룰루'));assert(!b.matchup_playbook.theirs.means.includes('노틸러스'));const f=run(1).coach.planboard;assert.equal(f.coverage.status,'CONDITIONAL_REFERENCE');assert.equal(f.matchup_playbook.supported,true);assert(f.matchup_playbook.theirs.means.includes('말파이트'));const unsupported=run(1).input;unsupported.enemies.find(p=>p.position==='TOP').champion='Garen';assert.equal(E.analyze(unsupported,c).coach.planboard.coverage.status,'UNSUPPORTED');")
 def test_key_spent_changes_allowed_gain_not_kill_or_entire_strength(self):
  self.node("const a=run(),b=run(0,{enemy_key:'SPENT'});assert.notEqual(a.coach.planboard.wave.combat,b.coach.planboard.wave.combat);assert(b.coach.planboard.matchup_playbook.ours.look_for.includes('소모'));assert.deepEqual(a.coach.periods,b.coach.periods);assert.equal(b.coach.planboard.fight.kill,'UNDETERMINED');assert(b.coach.planboard.wave.combat.includes('강력한 일격(P)'));")
 def test_paired_plan_respects_period_and_resource_gate(self):
  self.node("const b=run(2).coach.planboard.matchup_playbook,d=run(4).coach.planboard.matchup_playbook;assert(!b.theirs.means.includes('박치기(W)'));assert(!d.ours.means.includes('비전 이동(E)'));assert(!d.theirs.means.includes('사냥본능(R)'));assert(!d.theirs.look_for.includes('비전 이동(E)'));const spent=run(0,{enemy_key:'SPENT'}).coach.planboard.matchup_playbook;assert(!spent.theirs.means.includes('닻줄 견인(Q)로'));assert(spent.theirs.means.includes('다시'));for(const i of [0,2,3,4]){const x=run(i,{resources:'LOW'}).coach.planboard;assert.equal(x.matchup_playbook.ours.means,x.wave.combat);assert(x.matchup_playbook.ours.purpose.includes('수급'));}const absent=run(0,{}, {enemy_support:'ABSENT'}).coach.planboard.matchup_playbook;assert(!absent.theirs.means.includes('닻줄 견인'));assert(absent.theirs.means.includes('카이사'));const unknown=run(0,{wave:'UNKNOWN'}).coach.planboard;assert.equal(unknown.matchup_playbook.ours.means,unknown.wave.combat);")
 def test_quick_actions_have_scoped_effect_and_other_lane_evidence_is_independent(self):
  self.node("assert(!run(1).coach.planboard.quick_scenarios.some(q=>q.id==='KEY_SPENT'));assert(run(1,{}, {},'BALANCED','LEVEL2').coach.planboard.quick_scenarios.some(q=>q.id==='KEY_SPENT'));for(const i of [3,4])assert(!run(i).coach.planboard.quick_scenarios.some(q=>q.id==='KEY_SPENT'||q.id==='JUNGLE_LINK'));const x=run().input;x.own_champion='Ornn';x.own_position='TOP';const b=E.analyze(x,c).coach.planboard;assert.equal(b.overall.lanes.find(l=>l.position==='BOTTOM').priority,'ALLY');assert.equal(b.coverage.status,'UNSUPPORTED');")
 def test_threat_categories_and_jungle_links_have_scoped_means(self):
  self.node("const a=run().coach.planboard,q=a.fight.threats.find(t=>t.champion==='Nautilus'&&t.slot==='Q'),r=a.fight.threats.find(t=>t.champion==='Nautilus'&&t.slot==='R');assert.equal(q.response_kind,'BLOCK_LINE');assert.equal(r.response_kind,'EXPOSURE_AND_FOLLOWUP');assert(q.label.includes('노틸러스의 닻줄 견인(Q)'));assert(r.label.includes('노틸러스의 폭뢰(R)'));assert(!r.action.includes('미니언 뒤면 안전'));const j=run(0,{}, {ally_jungle:'AVAILABLE'}).coach.planboard;assert(j.overall.jungle_links.every(l=>l.observed_route===false));assert(j.overall.jungle_links.every(l=>l.basis==='DESIGN_HYPOTHESIS'));assert(j.overall.jungle_links.some(l=>l.jungler==='Sejuani'));assert(j.fight.start&&j.fight.stop&&j.fight.target);")
if __name__=='__main__':unittest.main()
